#!/usr/bin/env bash
# Generated by the Superpowers bootstrap — injects the using-superpowers skill at
# session start (@FORMAT@ output format).
case "$0" in */*) root="$(cd "${0%/*}/../.." && pwd)" ;; *) root="$(cd ../.. && pwd)" ;; esac
skill="$root/.agents/skills/using-superpowers/SKILL.md"
[ -r "$skill" ] || exit 0
content="$(<"$skill")"
content="${content//\\/\\\\}"
content="${content//\"/\\\"}"
content="${content//$'\n'/\\n}"
content="${content//$'\r'/\\r}"
content="${content//$'\t'/\\t}"
context="<EXTREMELY_IMPORTANT>\nYou have superpowers.\n\n**Below is the full content of your 'using-superpowers' skill - your introduction to using skills. For all other skills, use the 'Skill' tool:**\n\n${content}\n</EXTREMELY_IMPORTANT>"
case "@FORMAT@" in
  cursor)      printf '{"additional_context":"%s"}\n' "$context" ;;
  antigravity) printf '{"injectSteps":[{"systemMessage":{"systemMessage":"%s"}}]}\n' "$context" ;;
  *)           printf '{"hookSpecificOutput":{"hookEventName":"SessionStart","additionalContext":"%s"}}\n' "$context" ;;
esac
